// File: _colors.scss
$brand-primary: #6366f1;
$brand-secondary: #ec4899;

// File: style.scss
@use 'colors'; // Loads _colors.scss with namespace 'colors'

.header-banner {
  // Access variables through their namespace
  background-color: colors.$brand-primary;
  border-bottom: 2px solid colors.$brand-secondary;
}

// 1. Custom short alias namespace
@use 'theme-variables' as theme;

// 2. Wildcard namespace '*' (loads members directly without namespace prefix)
@use 'mixins' as *;

.card {
  // Using custom alias 'theme'
  background-color: theme.$surface-color;

  // Using mixin loaded globally via '*'
  @include center-flex;
}

// File: components/_index.scss (Entrypoint barrel file)
// Forwards all members from partials so consumers only need to import one file
@forward 'buttons';
@forward 'cards';
@forward 'alerts' as alert-*;

// File: main.scss (Consumer file)
@use 'components';

.dashboard-alert {
  // alert-* prefix was added via the @forward rule
  @include components.alert-warning;
}

@use 'sass:math';
@use 'sass:color';
@use 'sass:string';

$base-color: #3b82f6;

.badge {
  // Built-in color adjustment replacing legacy lighten/darken
  background-color: color.adjust($base-color, $lightness: 20%);
  border: 1px solid color.adjust($base-color, $lightness: -10%);

  // Built-in math calculation
  padding: math.div(12px, 2) math.clamp(8px, 16px, 24px);

  // Built-in string manipulation
  &::before {
    content: string.to-upper-case('new');
  }
}
